import heapq

def seat_reservation_manager(n, operations):
    heap = []
    next_fresh = 1
    results = []

    for op in operations:
        if op[0] == "reserve":
            if heap:
                seat = heapq.heappop(heap)
            else:
                seat = next_fresh
                next_fresh += 1
            results.append(seat)
        else:
            heapq.heappush(heap, op[1])

    return results

